/** Draw one frame of an animated sprite at an integer scale. */
export function drawAnim(ctx: CanvasRenderingContext2D, sprite: AnimSprite, frame: number, x: number, y: number, scale = 1): void {
  const rows = sprite.frames[frame % sprite.frames.length]!;
  for (let r = 0; r < rows.length; r++) {
    const row = rows[r]!;
    for (let c = 0; c < row.length; c++) {
      const ch = row[c]!;
      if (ch === '.') continue;
      ctx.fillStyle = sprite.colors[ch] ?? '#ff00ff';
      ctx.fillRect(x + c * scale, y + r * scale, scale, scale);
    }
  }
}
